"""Construye las series anuales de una capital y de su provincia a partir de las fuentes."""
import collections

import unicodedata

from . import fuentes as F
from .util import log


def norm_orden(s):
    """Orden alfabético como el del INE (sin tildes, sin mover artículos)."""
    s = unicodedata.normalize('NFKD', s)
    return ''.join(c for c in s if not unicodedata.combining(c)).lower()


def _paso(nombre, fn, avisos):
    try:
        fn()
    except Exception as e:  # noqa: BLE001 - una fuente caída no debe parar el resto
        avisos.append(f'{nombre}: {e}')
        log(f'  aviso, {nombre}: {e}')


def _put(filas, dic, campo, conv=None):
    for y, v in (dic or {}).items():
        if v is not None:
            filas[int(y)][campo] = conv(v) if conv else v


def _ine_prov(tabla, cpro, nult):
    """Intenta filtrar por provincia en la API; si la tabla no lo admite, descarga la tabla entera y filtra."""
    try:
        s = F.ine_provincia(tabla, cpro, nult)
        if s:
            return s
    except RuntimeError:
        pass
    return F.de_provincia(F.ine_completa(tabla, nult), cpro)


def serie_capital(cap, avisos):
    cod, cpro = cap['codigo'], cap['cpro']
    f = collections.defaultdict(dict)

    def padron():
        _put(f, F.anual(F.serie(F.ine_municipio(29005, cod, 40), r'\. Total\. Total habitantes')), 'poblacion_padron', int)

    def censo():
        _put(f, F.anual(F.serie(F.ine_municipio(68065, cod, 15), r'\. Total\. Total\. Todas las edades')), 'poblacion_censo_anual', int)
        h = F.censo2021_hogares().get(cod)
        if h:
            f[2021]['hogares_censo_2021'] = h

    def migraciones():
        s = F.ine_municipio(69767, cod, 15)
        for k in ('total', 'exterior', 'interior'):
            _put(f, F.anual(F.serie(s, r'\. Ambos sexos\. Saldo ' + k)), 'saldo_migratorio_' + k, int)

    def turisticas():
        d = F.serie(F.ine_municipio(39363, cod, 30), r'\. Viviendas turísticas')
        for (y, p), v in d.items():
            nombre = {2: 'feb', 5: 'may', 8: 'ago', 11: 'nov'}.get(p)
            if nombre:
                f[y]['turisticas_' + nombre] = int(v)

    def adrh():
        from .util import leer_capitales
        orden = [c['cpro'] for c in sorted(leer_capitales(), key=lambda c: norm_orden(c['provincia']))]
        tabla_dem = F.adrh_tabla(cpro, 'demograficos', cod, orden)
        tabla_renta = F.adrh_tabla(cpro, 'renta', cod, orden)
        s = F.ine_json(f"DATOS_TABLA/{tabla_dem}?tv=19:{F.id_municipio(cod)}&nult=20&tip=M", f'adrh_dem_{cod}')
        _put(f, F.anual(F.serie(s, r'Porcentaje de población española')), 'pct_espanoles_adrh')
        _put(f, F.anual(F.serie(s, r'Tamaño medio del hogar')), 'personas_por_hogar_adrh')
        _put(f, F.anual(F.serie(s, r'Porcentaje de hogares unipersonales')), 'pct_hogares_unipersonales_adrh')
        _put(f, F.anual(F.serie(s, r'\. Población\. ')), 'poblacion_adrh', int)
        for y, r in f.items():
            if r.get('poblacion_adrh') and r.get('pct_espanoles_adrh') is not None:
                r['extranjeros_aprox'] = round(r['poblacion_adrh'] * (100 - r['pct_espanoles_adrh']) / 100)
        s = F.ine_json(f"DATOS_TABLA/{tabla_renta}?tv=19:{F.id_municipio(cod)}&nult=20&tip=M", f'adrh_renta_{cod}')
        _put(f, F.anual(F.serie(s, r'Renta neta media por hogar')), 'renta_media_hogar', int)
        _put(f, F.anual(F.serie(s, r'Renta neta media por persona')), 'renta_media_persona', int)

    def compraventas():
        faltan = []
        for codx, campo in (('34010210', 'compraventas'), ('34010240', 'compraventas_nueva'), ('34010250', 'compraventas_segunda_mano')):
            d = F.mivau_municipio(codx, cap)
            if not d:
                faltan.append(codx)
            _put(f, d, campo, int)
        if faltan:
            raise RuntimeError(f'no encuentro {cap["capital"]} en las tablas {", ".join(faltan)}')

    def tasado():
        for campo, d in F.tasado_municipio(cap).items():
            _put(f, d, campo, round)

    def alquiler():
        idx = F.serpavi([cod], [cpro])
        for y, r in F.serpavi_serie(idx['mun'].get(cod)).items():
            f[y].update(r)

    def aeat():
        c, _ = F.aeat_viviendas(cap)
        for y, r in c.items():
            f[y].update(r)

    def catastro():
        d = F.catastro_propietarios('mun', cod)
        if not d:
            raise RuntimeError('sin datos del Catastro (País Vasco y Navarra tienen catastro propio)')
        for y, r in d.items():
            f[y].update(r)

    for nombre, fn in (('padrón', padron), ('censo', censo), ('migraciones', migraciones), ('viviendas turísticas', turisticas),
                       ('atlas de renta (ADRH)', adrh), ('compraventas', compraventas), ('valor tasado', tasado),
                       ('alquiler (SERPAVI)', alquiler), ('Hacienda (viviendas en el IRPF)', aeat),
                       ('Catastro (propietarios)', catastro)):
        _paso(nombre, fn, avisos)
    return [dict(anio=y, **f[y]) for y in sorted(f)]


def serie_provincia(cap, avisos):
    cpro = cap['cpro']
    alp = cap['alias_provincia']
    f = collections.defaultdict(dict)

    def poblacion():
        s = _ine_prov(59591, cpro, 110)
        _put(f, F.a_1_enero(F.serie(s, r'Todas las edades\. Total\. Total\.')), 'poblacion_ecp', int)
        _put(f, F.a_1_enero(F.serie(s, r'Todas las edades\. Española\. Total\.')), 'espanoles', int)
        _put(f, F.a_1_enero(F.serie(s, r'Todas las edades\. Extranjera\. Total\.')), 'extranjeros', int)

    def hogares():
        s = _ine_prov(60133, cpro, 40)
        _put(f, F.a_1_enero(F.serie(s, r'\. Total\. Hogares')), 'hogares', int)
        _put(f, F.a_1_enero(F.serie(s, r'\. 1\. Hogares')), 'hogares_1_persona', int)
        _put(f, F.a_1_enero(F.serie(_ine_prov(60134, cpro, 40), r'Tamaño medio')), 'personas_por_hogar')

    def natural():
        _put(f, F.suma_12(F.serie(F.de_provincia(F.ine_completa(6524, 260), cpro), r'.')), 'nacimientos', int)
        _put(f, F.suma_12(F.serie(F.de_provincia(F.ine_completa(6561, 260), cpro), r'.')), 'defunciones', int)

    def migraciones():
        ext = F.anual(F.serie(F.de_provincia(F.ine_completa(24329, 20), cpro), r'\. Total\. Saldo con el extranjero'))
        inter = F.anual(F.serie(F.de_provincia(F.ine_completa(24385, 20), cpro), r'Saldo de migración interprovincial\. Total'))
        s = _ine_prov(69764, cpro, 15)
        ext2 = F.anual(F.serie(s, r'Todas las edades\. Total\. Total\. Saldo exterior'))
        int2 = F.anual(F.serie(s, r'Todas las edades\. Total\. Total\. Saldo interior'))
        _put(f, {y: v for y, v in ext.items() if y <= 2020}, 'saldo_exterior', int)
        _put(f, {y: v for y, v in inter.items() if y <= 2020}, 'saldo_interior', int)
        _put(f, ext2, 'saldo_exterior', int)
        _put(f, int2, 'saldo_interior', int)

    def obra_nueva():
        _put(f, F.mivau_anual('32200500', alp), 'viviendas_iniciadas', int)
        _put(f, F.mivau_anual('32201000', alp), 'viviendas_terminadas', int)
        for y, r in F.parque_viviendas(alp).items():
            f[y].update(r)

    def compraventas():
        _put(f, F.mivau_trimestral('34010110', alp), 'compraventas_notarios', int)
        _put(f, F.mivau_trimestral('34010180', alp), 'compraventas_nueva_notarios', int)
        for y, r in F.mivau_compradores(alp).items():
            f[y].update(r)

    def registro_e_hipotecas():
        s = _ine_prov(6155, cpro, 25)
        _put(f, F.anual(F.serie(s, r'\. General\. Compraventa')), 'compraventas_registro', int)
        _put(f, F.anual(F.serie(s, r'\. Vivienda nueva\. Compraventa')), 'compraventas_nueva_registro', int)
        h = _ine_prov(76317, cpro, 260)
        _put(f, F.suma_12(F.serie(h, r'^Viviendas\. Número de hipotecas')), 'hipotecas_vivienda', int)

    def prestamos():
        from .util import leer_capitales
        if sum(1 for c in leer_capitales() if c['cien_prov'] == cap['cien_prov']) > 1:
            raise RuntimeError('el Notariado agrupa esta provincia con otra (Ceuta y Melilla); se usa solo el cálculo del registro')
        _put(f, F.cien_prestamos(int(cap['cien_prov'])), 'prestamos_compra_vivienda', int)

    def empresas():
        for y, (pct, nota) in F.eri_empresas(cap['ccaa']).items():
            f[y]['pct_empresas_ccaa'] = pct
            if nota != 'Registradores':
                f[y]['nota_empresas'] = nota

    def precios():
        _put(f, F.mivau_trimestral('35101000', alp, agg='media'), 'valor_tasado', round)
        _put(f, F.media_12(F.serie(_ine_prov(24081, cpro, 260), r'Índice general')), 'ipc_media', lambda v: round(v, 2))

    def turisticas():
        d = F.serie(_ine_prov(39364, cpro, 30), r'\. Viviendas turísticas')
        for (y, p), v in d.items():
            nombre = {2: 'feb', 5: 'may', 8: 'ago', 11: 'nov'}.get(p)
            if nombre:
                f[y]['turisticas_' + nombre] = int(v)

    def alquiler():
        idx = F.serpavi([cap['codigo']], [cpro])
        for y, r in F.serpavi_serie(idx['prov'].get(cpro)).items():
            f[y].update(r)

    def aeat():
        _, p = F.aeat_viviendas(cap)
        for y, r in p.items():
            f[y].update(r)

    def catastro():
        for y, r in F.catastro_propietarios('total').items():  # España (régimen común), para cuando falta el dato local
            f[y].update({k.replace('cat_', 'cat_nac_'): v for k, v in r.items()})
        d = F.catastro_propietarios('prov', alp)
        if not d:
            raise RuntimeError('sin datos del Catastro para la provincia (País Vasco y Navarra tienen catastro propio)')
        for y, r in d.items():
            f[y].update(r)

    for nombre, fn in (('Catastro (propietarios)', catastro), ('población', poblacion), ('hogares', hogares), ('nacimientos y defunciones', natural),
                       ('migraciones', migraciones), ('obra nueva y parque', obra_nueva), ('compraventas', compraventas),
                       ('registro e hipotecas', registro_e_hipotecas), ('préstamos (Notariado)', prestamos),
                       ('empresas (Registradores)', empresas), ('precios e IPC', precios), ('viviendas turísticas', turisticas),
                       ('alquiler (SERPAVI)', alquiler), ('Hacienda (viviendas en el IRPF)', aeat)):
        _paso(nombre, fn, avisos)
    return [dict(anio=y, **f[y]) for y in sorted(f)]
